pub fn expand_transitive_services_once(
    module_callees: Rc<Vec<Rc<ModuleCallees>>>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
) -> Rc<HashMap<String, Rc<ItemInfo>>> {
    module_callees
        .iter()
        .cloned()
        .fold(registry.clone(), |reg: _, m: _| {
            m.items
                .clone()
                .iter()
                .cloned()
                .fold(reg, |reg2: _, entry: _| {
                    let item_identity = entry.item_identity.clone();
                    match v1_rt::map_get(
                        &reg2,
                        crate::v1_std_core::callable_identity(item_identity.clone()),
                    ) {
                        Some(info) => {
                            let has_no_body = !entry.has_body.clone();
                            if has_no_body.clone() {
                                reg2.clone()
                            } else {
                                {
                                    let called = entry.called.clone();
                                    let extra = Rc::new({
                                        let mut __result = Vec::new();
                                        for edge in called.iter().cloned() {
                                            __result.extend(
                                                (*match (*edge.clone()).clone() {
                                                    CalleeEdge::ResolvedCallee {
                                                        identity: callee_identity,
                                                        ..
                                                    } => match v1_rt::map_get(
                                                        &reg2,
                                                        crate::v1_std_core::callable_identity(
                                                            callee_identity.clone(),
                                                        ),
                                                    ) {
                                                        Some(callee_info) => {
                                                            callee_info.service_names.clone()
                                                        }
                                                        std::option::Option::None => {
                                                            Rc::new(vec![])
                                                        }
                                                    },
                                                    CalleeEdge::PrimitiveCallee => Rc::new(vec![]),
                                                    CalleeEdge::FunctionValueCallee => {
                                                        Rc::new(vec![])
                                                    }
                                                    CalleeEdge::UnresolvedCallee {
                                                        spelling: _,
                                                        ..
                                                    } => Rc::new(vec![]),
                                                })
                                                .iter()
                                                .cloned(),
                                            );
                                        }
                                        __result
                                    });
                                    let merged = extra.iter().cloned().fold(
                                        info.service_names.clone(),
                                        |svc_list: Rc<Vec<String>>, svc: String| {
                                            if {
                                                let mut __found = false;
                                                for s in svc_list.iter().cloned() {
                                                    if (s.clone() == svc.clone()) {
                                                        __found = true;
                                                        break;
                                                    }
                                                }
                                                __found
                                            } {
                                                svc_list.clone()
                                            } else {
                                                v1_rt::rc_list_push(svc_list.clone(), svc.clone())
                                            }
                                        },
                                    );
                                    let same_count = ((merged.clone().len() as i64)
                                        == (info.service_names.clone().len() as i64));
                                    if same_count.clone() {
                                        reg2.clone()
                                    } else {
                                        v1_rt::rc_map_insert(
                                            reg2.clone(),
                                            crate::v1_std_core::callable_identity(
                                                item_identity.clone(),
                                            ),
                                            Rc::new(ItemInfo {
                                                name: info.name.clone(),
                                                module_name: info.module_name.clone(),
                                                kind: info.kind.clone(),
                                                service_names: merged.clone(),
                                                resource_names: info.resource_names.clone(),
                                                params: info.params.clone(),
                                                is_self_recursive: info.is_self_recursive.clone(),
                                                has_non_tail_self_call: info
                                                    .has_non_tail_self_call
                                                    .clone(),
                                            }),
                                        )
                                    }
                                }
                            }
                        }
                        std::option::Option::None => reg2.clone(),
                    }
                })
        })
}

