pub fn expand_transitive_services_loop(
    mut module_callees: Rc<Vec<Rc<ModuleCallees>>>,
    mut registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    mut remaining_passes: i64,
) -> Rc<ServiceEffectAnalysis> {
    loop {
        let before = total_service_count(registry.clone());
        let next = expand_transitive_services_once(module_callees.clone(), registry.clone());
        let after = total_service_count(next.clone());
        if (before.clone() == after.clone()) {
            break Rc::new(ServiceEffectAnalysis::EffectsComplete {
                registry: registry.clone(),
            });
        } else {
            if (remaining_passes.clone() <= 1) {
                break Rc::new(ServiceEffectAnalysis::EffectsIncomplete {
                    partial: next.clone(),
                    causes: Rc::new(vec![Rc::new(
                        EffectIncompleteness::ExpansionBudgetExhausted {
                            remaining_delta: (after.clone() - before.clone()),
                        },
                    )]),
                });
            } else {
                {
                    let __tco_0 = next.clone();
                    let __tco_1 = (remaining_passes - 1);
                    registry = __tco_0;
                    remaining_passes = __tco_1;
                    continue;
                }
            }
        }
    }
}

pub fn expand_transitive_services(
    modules: Rc<Vec<Rc<TypedModule>>>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    remaining_passes: i64,
) -> Rc<ServiceEffectAnalysis> {
    {
        let module_callees = build_module_callees(modules.clone());
        let unresolved = unresolved_callee_edges(module_callees.clone());
        let closed = expand_transitive_services_loop(
            module_callees.clone(),
            registry.clone(),
            remaining_passes.clone(),
        );
        match (*closed.clone()).clone() {
            ServiceEffectAnalysis::EffectsComplete {
                registry: closed_registry,
                ..
            } => {
                if ((unresolved.clone().len() as i64) == 0) {
                    Rc::new(ServiceEffectAnalysis::EffectsComplete {
                        registry: closed_registry.clone(),
                    })
                } else {
                    Rc::new(ServiceEffectAnalysis::EffectsIncomplete {
                        partial: closed_registry.clone(),
                        causes: unresolved.clone(),
                    })
                }
            }
            ServiceEffectAnalysis::EffectsIncomplete {
                partial, causes, ..
            } => Rc::new(ServiceEffectAnalysis::EffectsIncomplete {
                partial: partial.clone(),
                causes: v1_rt::concat(unresolved.clone(), causes.clone()),
            }),
        }
    }
}

pub fn check_service_field_access_node(
    base_type: Rc<Node>,
    field: String,
    service_registry: Rc<HashMap<String, Rc<Vec<Rc<OpEntry>>>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<Rc<Node>> {
    if ((base_type.connective.clone() == Connective::NoConnective)
        && ((base_type.children.clone().len() as i64) == 0))
    {
        {
            let path = v1_rt::concat(
                v1_rt::concat(
                    crate::v1_std_core::authored_name_at(source_indices.clone(), base_type.clone()),
                    ".".to_string(),
                ),
                field.clone(),
            );
            match v1_rt::map_get(&service_registry, path.clone()) {
                Some(_) => Some(crate::v1_compiler_infer_types::nominal_type_ref(
                    path.clone(),
                )),
                std::option::Option::None => std::option::Option::None,
            }
        }
    } else {
        std::option::Option::None
    }
}

